static inline void skb_dst_drop(struct sk_buff *skb) /* <=== skb_dst_drop */ 
{
	if (skb->_skb_refdst) {
		refdst_drop(skb->_skb_refdst);
		skb->_skb_refdst = 0UL;
	}
}

static inline struct inet_sock *inet_sk(const struct sock *sk) /* <=== inet_sk */ 
{
	return (struct inet_sock *)sk;
}

static inline int rcu_read_lock_held(void) /* <=== rcu_read_lock_held */ 
{
	return 1;
}

static inline void skb_dst_force(struct sk_buff *skb) /* <=== skb_dst_force */ 
{
	if (skb_dst_is_noref(skb)) {
		WARN_ON(!rcu_read_lock_held());
		skb->_skb_refdst &= ~SKB_DST_NOREF;
		dst_clone(skb_dst(skb));
	}
}

static inline void refdst_drop(unsigned long refdst) /* <=== refdst_drop */ 
{
	if (!(refdst & SKB_DST_NOREF))
		dst_release((struct dst_entry *)(refdst & SKB_DST_PTRMASK));
}

static inline struct dst_entry *dst_clone(struct dst_entry *dst) /* <=== dst_clone */ 
{
	if (dst)
		atomic_inc(&dst->__refcnt);
	return dst;
}

